51	            absolute_layout_bounds: FxHashMap::default(),
52	            absolute_outer_origins: FxHashMap::default(),
53	            computed_layouts: FxHashSet::default(),
54	            layout_bounds_scratch_space: Vec::new(),
55	        }
56	    }
