use gpui::{Style, StyleRefinement, prelude::*};

fn main() {
    // 补丁一：只改 flex 方向，不碰 display
    let patch = StyleRefinement::default().flex_col();
    let mut composed = Style::default();
    composed.refine(&patch);

    // 补丁二：显式改 display，再合成一份对比
    let patch_flex = StyleRefinement::default().flex();
    let mut composed_flex = Style::default();
    composed_flex.refine(&patch_flex);

    println!("裸补丁合成后 display = {:?}", composed.display);
    println!("带 .flex() 合成后 display = {:?}", composed_flex.display);
}
```

两个写法要点：链式样式方法是**按值消费**的（`fn flex_col(mut self) -> Self`），所以必须像 `let patch = StyleRefinement::default().flex_col();` 这样承接返回值，写成 `let mut p = ...; p.flex_col();` 会把修改结果丢掉；`refine` 方法来自 `Refineable` trait，而它在 gpui prelude 里（[src/prelude.rs:L5-L9](https://github.com/zed-industries/zed/blob/fa00dccc42311f8dc71c533105488b0dbd518138/crates/gpui/src/prelude.rs#L5-L9)），`use gpui::prelude::*` 不能省。crate 自己的测试用的正是这个链式形式（[src/style.rs:L1516](https://github.com/zed-industries/zed/blob/fa00dccc42311f8dc71c533105488b0dbd518138/crates/gpui/src/style.rs#L1516)：`style.refine(&StyleRefinement::default().text_size(px(20.0)))`）。

