#![cfg_attr(target_family = "wasm", no_main)]

use gpui::{App, Bounds, Context, Render, TextStyle, Window, WindowBounds, WindowOptions, div, prelude::*, rgb, size, px};

struct InheritDemo {}

impl Render for InheritDemo {
    fn render(&mut self, _window: &mut Window, _cx: &mut Context<Self>) -> impl IntoElement {
        div()
            .flex().flex_col().gap_4().p_4().size_full()
            // 根节点设置主题级文字样式：深灰 + 大字号
            .text_color(rgb(0x333333))
            .text_size(px(20.))
            .child(
                // 子元素 A：什么都不设，完全继承
                div().child("A. 继承根样式（20px 深灰）"),
            )
            .child(
                // 子元素 B：只覆盖颜色；其内部的孙元素不设任何样式
                div().text_color(rgb(0xB00020))
                    .child("B. 覆盖颜色（红）")
                    .child(div().child("B 的子元素：红且仍是 20px —— 覆盖后的值继续下传")),
            )
            .child(
                // 子元素 C：只覆盖字号
                div().text_sm().text_color(rgb(0x00695C]))
                    .child("C. 覆盖字号为 text_sm（0.875rem）"),
            )
    }
}

fn run_example() {
    gpui_platform::application().run(|cx: &mut App| {
        let bounds = Bounds::centered(None, size(px(760.), px(420.)), cx);
        cx.open_window(
            WindowOptions {
                window_bounds: Some(WindowBounds::Windowed(bounds)),
                ..Default::default()
            },
            |_, cx| cx.new(|_| InheritDemo {}),
        )
        .unwrap();
        cx.activate(true);
    });
}

#[cfg(not(target_family = "wasm"))]
fn main() {
    run_example();
}

#[cfg(target_family = "wasm")]
#[wasm_bindgen::prelude::wasm_bindgen(start)]
pub fn start() {
    gpui_platform::web_init();
    run_example();
}
```

